def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("Invalid nanoseconds value: {}".format(nanoseconds))
    if tz is not None:
        try:
            tz = pytz.timezone(tz)
        except pytz.UnknownTimeZoneError:
            raise ValueError("Invalid timezone: {}".format(tz))
    return Time(nanoseconds, tz)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return value.total_seconds()
    except AttributeError:
        raise TypeError("Invalid input type: expected timedelta, got {}".format(type(value)))

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, Time):
        raise TypeError("Expected Time object, got {}".format(type(value)))
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point instance")

    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.data.keys())
    except AttributeError:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._protocol_handlers[version] for version in cls._protocol_handlers}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version in cls._protocol_handlers:
            return {protocol_version: cls._protocol_handlers[protocol_version]}
        else:
            return {}

def index(self, key):
