def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # Step 1: Get all files in the folder
    files = os.listdir(folder)

    # Step 2: Filter out non-XML files
    xml_files = [file for file in files if file.endswith('.xml')]

    # Step 3: Group files by their XML basename
    basename_to_files = {}
    for file in xml_files:
        basename = os.path.splitext(file)[0]
        if basename not in basename_to_files:
            basename_to_files[basename] = []
        basename_to_files[basename].append(file)

    # Step 4: Get data from each group of files
    data = {}
    for basename, files in basename_to_files.items():
        data[basename] = _get_data_from_files(files)

    return data

def _get_data_from_files(files):
    # Step 1: Get the first file in the group
    first_file = files[0]

    # Step 2: Get the root element of the first file
    root = ET.parse(first_file).getroot()

    # Step 3: Get the namespace of the root element
    namespace = root.tag.split('}')[0].strip('{')

    # Step 4: Get the data from the first file
    data = _get_data_from_file(first_file, namespace)

    # Step 5: Get the data from the remaining files
    for file in files[1:]:
        data.update(_get_data_from_file(file, namespace))

    return data

def _get_data_from_file(file, namespace):
    # Step 1: Get the root element of the file
    root = ET.parse(file).getroot()

    # Step 2: Get the data from the root element
    data = _get_data_from_element(root, namespace)

    return data

def _get_data_from_element(element, namespace):
    # Step 1: Get the tag name of the element
    tag_name = element.tag.split('}')[1]

    # Step 2: Get the data from the element
    data = {}
    for child in element:
        if child.tag == f'{{{namespace}}}name':
            data['name'] = child.text
        elif child.tag == f'{{{namespace}}}version':
            data['version'] = child.text
        elif child.tag == f'{{{namespace}}}description':
            data['description'] = child.text
        elif child.tag == f'{{{namespace}}}license':
            data['license'] = child.text
        elif child.tag == f'{{{namespace}}}author':
            data['author'] = child.text
        elif child.tag == f'{{{namespace}}}homepage':
            data['homepage'] = child.text
        elif child.tag == f'{{{namespace}}}repository':
            data['repository'] = child.text
        elif child.tag == f'{{{namespace}}}bugs':
            data['bugs'] = child.text
        elif child.tag == f'{{{namespace}}}keywords':
            data['keywords'] = child.text
        elif child.tag == f'{{{namespace}}}contributors':
            data['contributors'] = child.text
        elif child.tag == f'{{{namespace}}}dependencies':
            data['dependencies'] = child.text
        elif child.tag == f'{{{namespace}}}devDependencies':
            data['devDependencies'] = child.text
        elif child.tag == f'{{{namespace}}}peerDependencies':
            data['peerDependencies'] = child.text
        elif child.tag == f'{{{namespace}}}optionalDependencies':
