def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Step 1: Determine the type of self
    if isinstance(self, dict):
        # Step 2: If self is a dict, sort the keys and format the dict
        sorted_keys = sorted(self.keys())
        pretty_dict = "{\n"
        for key in sorted_keys:
            pretty_dict += f"{indent * ' '}{key}: {self[key]},\n"
        pretty_dict += f"{indent * ' '}}"
        return pretty_dict
    elif isinstance(self, list):
        # Step 3: If self is a list, format the list
        pretty_list = "[\n"
        for item in self:
            pretty_list += f"{indent * ' '}{item},\n"
        pretty_list += f"{indent * ' '}]"
        return pretty_list
    else:
        # Step 4: If self is not a dict or list, return a string representation of self
        return str(self)

