def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string")
        if not command:
            raise ValueError("Command cannot be empty")
    if not isinstance(args, (list, tuple)):
        args = [args]
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Argument must be a string")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Working directory must be a string")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment must be a dictionary")
    if not isinstance(verbose, bool):
        raise ValueError("Verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("Hide stderr must be a boolean")

    # Create a new process
    process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Read from stdout and stderr
    stdout, stderr = process.communicate()

    # Check if the command was successful
    if process.returncode != 0:
        raise RuntimeError("Command failed with exit code {}".format(process.returncode))

    # Return the output
    return stdout.decode("utf-8")

