def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Validate the root directory
    if not self.root_dir.exists():
        raise ValueError("Root directory does not exist")

    # Validate the objects in the root directory
    for obj in self.root_dir.iterdir():
        num_objects += 1
        if validate_objects and not self.validate_object(obj):
            continue
        if check_digests and not self.check_digest(obj):
            continue
        good_objects += 1

    # Validate the subdirectories
    for subdir in self.root_dir.iterdir():
        if not subdir.is_dir():
            continue
        for obj in subdir.iterdir():
            num_objects += 1
            if validate_objects and not self.validate_object(obj):
                continue
            if check_digests and not self.check_digest(obj):
                continue
            good_objects += 1

    return num_objects, good_objects

