def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.upper()
        if size.endswith("K"):
            return int(size[:-1]) * 1000
        elif size.endswith("M"):
            return int(size[:-1]) * 1000000
        elif size.endswith("G"):
            return int(size[:-1]) * 1000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid file size")

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key not in result:
                result[key] = value
            else:
                result[key] += value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Step 1: Parse the URL and extract the custom string items
    parsed_url = urlparse(url)
    custom_string_items = re.findall(r'\{([^}]+)\}', parsed_url.path)

    # Step 2: Replace the custom string items with values from args
    for item in custom_string_items:
        if item in url_args:
            parsed_url.path = parsed_url.path.replace('{' + item + '}', url_args[item])

    # Step 3: Return the modified URL
    return parsed_url.geturl()

