def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'win32':
        return _split_windows(s)
    else:
        return _split_posix(s)

def _split_windows(s):
    # Use a regular expression to split the string into tokens,
    # treating double quotes as a special case.
    tokens = re.split(r'(\"[^\"]*\")', s)
    result = []
    for token in tokens:
        if token.startswith('"') and token.endswith('"'):
            # If the token is surrounded by double quotes, remove them.
            result.append(token[1:-1])
        else:
            # Otherwise, split the token by spaces.
            result.extend(token.split())
    return result

def _split_posix(s):
    # Use a regular expression to split the string into tokens,
    # treating single quotes as a special case.
    tokens = re.split(r"('[^']*')", s)
    result = []
    for token in tokens:
        if token.startswith("'") and token.endswith("'"):
            # If the token is surrounded by single quotes, remove them.
            result.append(token[1:-1])
        else:
            # Otherwise, split the token by spaces.
            result.extend(token.split())
    return result

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Step 1: Check if the archive exists
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive file {archive_path} does not exist")

    # Step 2: Create a temporary directory to extract the archive
    tmp_dir = tempfile.mkdtemp(dir=tmp_path)

    # Step 3: Extract the archive
    try:
        subprocess.run(["tar", "-xvf", archive_path, "-C", tmp_dir], check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}") from e

    # Step 4: Find the extracted repository directory
    repo_dir = None
    for root, dirs, files in os.walk(tmp_dir):
        if filename and filename in files:
            repo_dir = root
            break

    # Step 5: Return the file repo url
    if repo_dir:
        return f"file://{repo_dir}"
    else:
        raise RuntimeError(f"Failed to find repository directory in extracted archive {archive_path}")

