def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ.copy()
    for command in commands:
        try:
            subprocess.check_call(command, args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print(e.output.decode("utf-8"), end="")
            else:
                print(e.output.decode("utf-8"), file=sys.stderr, end="")
            if verbose:
                print(f"Command '{command}' failed with exit code {e.returncode}.", file=sys.stderr)
            return e.returncode
        except OSError as e:
            if hide_stderr:
                print(e.strerror, end="")
            else:
                print(e.strerror, file=sys.stderr, end="")
            if verbose:
                print(f"Command '{command}' failed with error {e.errno}.", file=sys.stderr)
            return e.errno
    return 0

