    :return: Dictionary with data loaded from a spec (YAML) file.
    """
    try:
        spec_dict = yaml.safe_load(spec_content)
        required_fields = ['name', 'version', 'description', 'author', 'email']
        for field in required_fields:
            if field not in spec_dict:
                raise IRValidatorException(f'Missing required field: {field}')
        return spec_dict
    except yaml.YAMLError as e:
        raise IRValidatorException(f'Invalid YAML content: {e}')

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary containing the resolved argument values.
    """
    # Initialize the resolved argument values dictionary
    resolved_args = {}

    # Iterate over the arguments in the spec
    for arg_name, arg_spec in self.spec.items():
        # Check if the argument has a default value
        if arg_spec.get("default") is not None:
            # If the argument has a default value, use it as the resolved value
            resolved_args[arg_name] = arg_spec["default"]
        else:
            # If the argument does not have a default value, try to get it from the other sources
            try:
                # Try to get the argument value from the environment variables
                resolved_args[arg_name] = os.environ[arg_name]
            except KeyError:
                # If the argument is not found in the environment variables, try to get it from the config file
                try:
                    resolved_args[arg_name] = self.config[arg_name]
                except KeyError:
                    # If the argument is not found in the config file, use the default value from the spec
                    resolved_args[arg_name] = arg_spec["default"]

    return resolved_args

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # Step 1: Define a dictionary to store the deprecated options
    deprecated_args = {}

    # Step 2: Iterate over the options and check if they have been deprecated
    for option in self.options:
        if option.deprecated:
            # If the option is deprecated, add it to the dictionary
            deprecated_args[option.name] = option.deprecated_by

    # Step 3: Return the dictionary of deprecated options
    return deprecated_args

